import{_ as t,o as a,c as i,a5 as s}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"プラグインのランタイムと信頼の制限","description":"","frontmatter":{"title":"プラグインのランタイムと信頼の制限","docId":"developer.plugins.runtimes","translationKey":"developer.plugins.runtimes","locale":"ja","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a249fa36fa53f3bfe7da57fdd25a445e593517946f80ac7e891b54d95cdc17d","translationRevision":"28276632fbebdb6027f53c89983021b670fad346925fac66f50accb37c55dac8","order":260},"headers":[],"relativePath":"ja/developer/plugins/runtimes.md","filePath":"ja/developer/plugins/runtimes.md","lastUpdated":1794611623000}'),d={name:"ja/developer/plugins/runtimes.md"};function r(n,e,o,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="plugin-runtimes-and-trust-limits" tabindex="-1">プラグインのランタイムと信頼の制限 <a class="header-anchor" href="#plugin-runtimes-and-trust-limits" aria-label="Permalink to &quot;プラグインのランタイムと信頼の制限 {#plugin-runtimes-and-trust-limits}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>依存と信頼がホストに合う実行形式を選びます。<a href="./">概要</a> を読み、実際のビルドに対してマニフェストを検証し、読み込み前に対象固有の制限を確認します。プロトコル互換性、ネイティブ ABI 互換性、権限付与は独立した検査です。</p><h2 id="choose-an-implemented-runtime" tabindex="-1">実装済みランタイムを選ぶ <a class="header-anchor" href="#choose-an-implemented-runtime" aria-label="Permalink to &quot;実装済みランタイムを選ぶ {#choose-an-implemented-runtime}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ランタイム</th><th>実行</th><th>信頼と可搬性</th></tr></thead><tbody><tr><td><code>native</code></td><td><code>libloading</code> C ABI</td><td>信頼済みのプロセス内コード、対象固有</td></tr><tr><td><code>process</code></td><td>独立実行ファイル、フレーム化 stdin/stdout</td><td>クラッシュ分離、通常ユーザーの OS 権限</td></tr><tr><td><code>napi-vm</code></td><td><code>rquickjs</code> 経由で事前コンパイル JS を QuickJS 実行</td><td>ホスト処理は既定で拒否。任意のネイティブアドオンで信頼条件が変わる</td></tr><tr><td><code>declarative</code></td><td>検証済み連携記述子</td><td>ゲストプログラムなし。ホストブローカーで処理</td></tr><tr><td><code>wasm</code></td><td>任意の実行枠</td><td>通常ビルドでは汎用エンジン無効</td></tr></tbody></table><p>ネイティブ ABI v1 は小さな C テーブルを通して直列化バイト列を交換し、Rust コンテナー、トレイトオブジェクト、Future は渡しません。ライブラリは終了まで読み込んだままです。process のフレームは little-endian u32 の長さと JSON バイト列で、改行区切り制御 RPC とは異なります。診断出力をフレーム用 stdout に混ぜないでください。</p><h2 id="understand-quickjs-compatibility" tabindex="-1">QuickJS 互換性を理解する <a class="header-anchor" href="#understand-quickjs-compatibility" aria-label="Permalink to &quot;QuickJS 互換性を理解する {#understand-quickjs-compatibility}&quot;">​</a></h2><p><code>napi-vm</code> 名は維持しますが、独立した純 Rust インタープリターという旧説明は過去のものです。ゲストにあるのは文書化された互換グローバルで、完全な Node 環境ではありません。<code>napi_get_uv_event_loop</code> は非対応です。ネイティブ <code>.node</code> は意図的に信頼し、許可リストと SHA-256 検証を使うプロセス内経路です。JavaScript ランタイムの名前で安全になるわけではありません。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-loader</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span></code></pre></div><p>完全なネイティブアドオンの検証に不足ツールが必要なら、対象ローダーテストを使います。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>マニフェスト解析は読み込み前に非対応のプロトコル・ABI を拒否します。Android は可搬 QuickJS と有効な Android/Bionic process を許可し、動的ネイティブライブラリと <code>.node</code> を拒否します。Linux/glibc 成果物は Android 用 process プラグインではありません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>ネイティブライブラリ置換後は非公開ホストを再起動します。起動がタイムアウトして不明になったら、管理側がワーカー ID を保持して置換を禁止する場合があります。終了成功を宣言して迂回しません。イベントバッファーは有限で遅れが報告され、起動時の送出は永続待機列ではありません。<a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-loader/src" target="_blank" rel="noreferrer">ローダー実装</a> が現行エンジンとライフサイクルの正本です。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>現在の制限は QuickJS メモリ 512 MiB、スタック 2 MiB、呼び出しごとの割り込み予算、プロトコルフレーム 16 MiB、インスタンスごとに最大 128 件の待機呼び出しです。副作用中止は保証しません。プロセスの timeout は終了・削除しますが、ネイティブ呼び出しは安全に強制終了できず、インスタンスを保持します。OS の副作用が既に起きた場合もあります。置換・再試行前に元結果とライフサイクルを調べます。信頼済み <code>.node</code> は JS の能力境界外でホスト権限を使います。</p>`,16)])])}const k=t(d,[["render",r]]);export{u as __pageData,k as default};
